mapper.select:
select plant_manage.plant_id, plant_manage.plant_name, plant_manage.plant_type, plant_manage.plant_lifeCycle, plant_manage.area_id, plant_manage.create_date,
       plant_manage.create_by, plant_manage.update_date, plant_manage.update_by, plant_manage.del_flag,area_manage.area_name from plant_manage
left join area_manage on area_manage.area_id = plant_manage.area_id

     and plant_manage.plant_name like concat('%', #{plantName}, '%')
     and plant_manage.plant_type = #{plantType}
     and plant_manage.plant_lifeCycle = #{plantLifecycle}

     and plant_manage.create_date between #{startCreateDate} and #{stopCreateDate}
     and plant_manage.update_date = #{updateDate}
     and plant_manage.del_flag =0 
     and plant_manage.user_id = #{userId}

order by plant_manage.create_date DESC

mapper.update:
update plant_manage
plant_name = #{plantName}, plant_type = #{plantType}, plant_lifeCycle = #{plantLifecycle}, area_id = #{areaId}, create_date = #{createDate}, create_by = #{createBy}, update_date = #{updateDate}, update_by = #{updateBy}, del_flag = #{delFlag},
where plant_id = #{plantId}

